/**
 * Builds `src/data/captions.ts` from the supplied Cartesia timestamp JSON.
 *
 *   node scripts/build-captions.mjs
 *
 * The script groups the word-level timestamps into short, readable Bengali
 * caption phrases (punctuation-aware, max ~5 words / ~3s), keeps the original
 * word timings, and marks brand/benefit keywords for accent highlighting.
 * The generated file is committed, so this only needs to be re-run if the
 * narration or the timestamp JSON changes.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const JSON_PATH = path.join(ROOT, 'data', 'voiceover-timestamps.json');
const OUT_PATH = path.join(ROOT, 'src', 'data', 'captions.ts');
const FPS = 30;

const MAX_WORDS = 5;
const MAX_DURATION = 3.15;
const MAX_CHARS = 40;

const HIGHLIGHT = new Set([
  'facebook', 'facebook-এর', 'page',
  'অর্ডার', 'অর্ডারও', 'কাস্টমার', 'কাস্টমারও', 'কাস্টমারের',
  'ওয়েবসাইট', 'ওয়েবসাইটে',
  'দাম', 'কালার', 'সাইজ', 'ডেলিভারি',
  'স্টক', 'কুরিয়ার', 'ইন্টিগ্রেশন', 'ম্যানেজমেন্ট',
  'ম্যানুয়ালি', 'প্রতিযোগিতা', 'প্রতিযোগিতায়', 'প্রশ্নোত্তর',
  'বিশ্বাস', 'বিশ্বাসযোগ্যভাবে', 'শক্তিশালী', 'প্ল্যাটফর্ম', 'প্ল্যাটফর্মে',
  'সময়', 'বাঁচছে', 'আইডিয়া', 'কাস্টমভাবে', 'যোগাযোগ',
  'buy', 'now', 'wp', 'expert', 'solution',
]);

const raw = JSON.parse(fs.readFileSync(JSON_PATH, 'utf8'));
const segment = raw.segments[0];

const normalize = (t) => t.trim();

const words = segment.words
  .map((w) => ({ text: w.text, start: w.start_time, end: w.end_time }))
  .filter((w) => normalize(w.text).length > 0)
  .map((w) => ({ ...w, text: normalize(w.text) }));

if (words.length === 0) {
  throw new Error('No word timings found in the timestamp JSON.');
}

// Split on punctuation, then on length/duration limits, producing balanced chunks.
const clauses = [];
let clause = [];
for (const word of words) {
  clause.push(word);
  if (/[।?!,;:—]$/.test(word.text)) {
    clauses.push(clause);
    clause = [];
  }
}
if (clause.length) clauses.push(clause);

const chunks = [];
for (const c of clauses) {
  if (c.length <= 1) {
    chunks.push(c);
    continue;
  }
  const duration = c[c.length - 1].end - c[0].start;
  const chars = c.reduce((n, w) => n + w.text.length + 1, 0);
  if (c.length <= MAX_WORDS && duration <= MAX_DURATION && chars <= MAX_CHARS) {
    chunks.push(c);
    continue;
  }
  // Balanced split: aim for equal word counts across the pieces.
  const parts = Math.max(
    2,
    Math.ceil(c.length / MAX_WORDS),
    Math.ceil(duration / MAX_DURATION)
  );
  const perPart = Math.ceil(c.length / parts);
  for (let i = 0; i < c.length; i += perPart) {
    chunks.push(c.slice(i, i + perPart));
  }
}

// Merge one-word orphans into a neighbour when the result still reads comfortably.
const merged = [];
for (const chunk of chunks) {
  const prev = merged[merged.length - 1];
  const canMerge =
    prev &&
    prev.length + chunk.length <= MAX_WORDS + 1 &&
    chunk[chunk.length - 1].end - prev[0].start <= MAX_DURATION + 0.5;
  if (chunk.length === 1 && canMerge) {
    prev.push(...chunk);
  } else {
    merged.push([...chunk]);
  }
}

const cues = merged.map((chunk, index) => {
  const firstStart = chunk[0].start;
  const lastEnd = chunk[chunk.length - 1].end;
  const nextStart = merged[index + 1]?.[0]?.start ?? lastEnd + 1;
  const prevEnd = index === 0 ? 0 : merged[index - 1].slice(-1)[0].end;

  const startSec = Math.max(prevEnd - 0.02, firstStart - 0.12);
  const endSec = Math.min(nextStart - 0.03, lastEnd + 0.42);

  return {
    id: `c${index + 1}`,
    startFrame: Math.round(Math.max(0, startSec) * FPS),
    endFrame: Math.round(Math.max(endSec, lastEnd + 0.12) * FPS),
    words: chunk.map((w) => ({
      text: w.text,
      startFrame: Math.round(w.start * FPS),
      endFrame: Math.round(w.end * FPS),
      highlight: HIGHLIGHT.has(w.text.toLowerCase().replace(/[।?!,;:—"“”]/g, '')),
    })),
  };
});

// Guarantee a clean, non-overlapping timeline.
for (let i = 1; i < cues.length; i++) {
  if (cues[i].startFrame < cues[i - 1].endFrame) {
    cues[i].startFrame = cues[i - 1].endFrame + 1;
  }
  if (cues[i].endFrame <= cues[i].startFrame) {
    cues[i].endFrame = cues[i].startFrame + 8;
  }
}

const q = (s) => JSON.stringify(s);
const lines = [];
lines.push('// AUTO-GENERATED by scripts/build-captions.mjs — do not edit by hand.');
lines.push('// Source: data/voiceover-timestamps.json (Cartesia word-level timings).');
lines.push('');
lines.push('export interface CaptionWord {');
lines.push('  text: string;');
lines.push('  startFrame: number;');
lines.push('  endFrame: number;');
lines.push('  highlight: boolean;');
lines.push('}');
lines.push('');
lines.push('export interface CaptionCue {');
lines.push('  id: string;');
lines.push('  startFrame: number;');
lines.push('  endFrame: number;');
lines.push('  words: CaptionWord[];');
lines.push('}');
lines.push('');
lines.push('export const CAPTION_CUES: CaptionCue[] = [');
for (const cue of cues) {
  lines.push('  {');
  lines.push(`    id: ${q(cue.id)},`);
  lines.push(`    startFrame: ${cue.startFrame},`);
  lines.push(`    endFrame: ${cue.endFrame},`);
  lines.push('    words: [');
  for (const w of cue.words) {
    lines.push(
      `      { text: ${q(w.text)}, startFrame: ${w.startFrame}, endFrame: ${w.endFrame}, highlight: ${w.highlight} },`
    );
  }
  lines.push('    ],');
  lines.push('  },');
}
lines.push('];');
lines.push('');

fs.writeFileSync(OUT_PATH, lines.join('\n'), 'utf8');

const longest = cues.reduce((a, b) => (b.words.length > a.words.length ? b : a));
const longestChars = cues.reduce((a, b) =>
  b.words.reduce((n, w) => n + w.text.length, 0) >
  a.words.reduce((n, w) => n + w.text.length, 0)
    ? b
    : a
);
console.log(
  `Wrote ${cues.length} caption cues to ${path.relative(ROOT, OUT_PATH)} ` +
    `(max ${longest.words.length} words, max ${longestChars.words
      .map((w) => w.text)
      .join(' ').length} chars).`
);
console.log(
  `Narration: ${words[0].start}s → ${words[words.length - 1].end}s, ${words.length} words.`
);
